import boto3

from database_models import deserialize_document


def fetch_document(document_id, config):
    table = boto3.resource("dynamodb", region_name=config["region"]).Table(config["table_name"])
    response = table.get_item(Key={config["key_field"]: document_id})
    item = response.get("Item")
    if item:
        return deserialize_document(item)
    return None

import boto3


def get_dynamodb_client(region, table_name):
    return boto3.resource("dynamodb", region_name=region).Table(table_name)

from decimal import Decimal


def deserialize_document(item):
    if not item:
        return None
    return {k: v if not isinstance(v, Decimal) else float(v) for k, v in item.items()}


def deserialize_documents(items):
    return [deserialize_document(item) for item in items]

from fetch_document import fetch_document


def record_summary(document_id, config):
    document = fetch_document(document_id, config)
    if document:
        return {"summary": document}
    return None

import re


def record_text_safety(document):
    if not document:
        return True
    for field in document:
        if isinstance(document[field], str):
            if re.search(r"[^a-zA-Z0-9\s]", document[field]):
                return False
    return True

import boto3


def record_translate(document, target_language, config):
    translate = boto3.client('translate', region_name=config['region'])
    translated_document = {}
    for field in document:
        if isinstance(document[field], str):
            response = translate.translate_text(Text=document[field], SourceLanguageCode='en', TargetLanguageCode=target_language)
            translated_document[field] = response['TranslatedText']
        else:
            translated_document[field] = document[field]
    return translated_document
